CREATE OR REPLACE FUNCTION public.rls_auto_enable() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_dau() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public' AS $function$
BEGIN
  RETURN (SELECT count(DISTINCT id)::integer FROM auth.users WHERE last_sign_in_at >= now() - interval '1 day');
END;
$function$

CREATE OR REPLACE FUNCTION public.get_mau() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public' AS $function$
BEGIN
  RETURN (SELECT count(DISTINCT id)::integer FROM auth.users WHERE last_sign_in_at >= now() - interval '30 days');
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public' AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, signup_source)
  VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_app_meta_data->>'provider', 'email'))
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'public' AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_retention(days integer) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public' AS $function$
DECLARE
  eligible integer;
  retained integer;
BEGIN
  SELECT count(*)::integer INTO eligible FROM auth.users WHERE created_at <= now() - (days || ' days')::interval;
  IF eligible = 0 THEN RETURN 0; END IF;
  SELECT count(*)::integer INTO retained FROM auth.users
    WHERE created_at <= now() - (days || ' days')::interval
      AND last_sign_in_at >= now() - (days || ' days')::interval;
  RETURN round((retained::numeric / eligible::numeric) * 100, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_shared_round(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare link public.share_links; snapshot jsonb;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then raise exception 'invalid link'; end if;
  select * into link from public.share_links where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
  if not found then raise exception 'invalid link'; end if;
  if link.revoked_at is not null then raise exception 'revoked link'; end if;
  if link.expires_at <= now() then raise exception 'expired link'; end if;
  select r.snapshot into snapshot from public.published_rounds r where r.contest_id=link.contest_id;
  return public.sanitize_shared_round(snapshot);
end $function$

CREATE OR REPLACE FUNCTION public.post_message(p_token text, p_session text, p_name text, p_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare cid uuid; session_hash text; at_time timestamptz;
begin
  cid := public.chat_contest(p_token);
  if p_session is null or p_session !~ '^[a-f0-9]{64}$'
    or p_name is null or char_length(btrim(p_name)) not between 1 and 30
    or p_body is null or char_length(btrim(p_body)) not between 1 and 500 then
    raise exception 'invalid message';
  end if;
  -- Same lock as revoke/publish: concurrent posts cannot bypass round/session limits.
  perform 1 from public.published_rounds where contest_id=cid for update;
  perform public.chat_contest(p_token); -- Revocation/expiry may have occurred while waiting.
  at_time := clock_timestamp();
  session_hash := encode(sha256(convert_to(p_session,'UTF8')),'hex');
  -- Removed messages still count. A new token does not reset the round's limits.
  if (select count(*) from public.round_messages where contest_id=cid and sender_session_hash=session_hash
        and created_at > at_time - interval '30 seconds') >= 5
    or (select count(*) from public.round_messages where contest_id=cid
        and created_at > at_time - interval '1 minute') >= 60 then
    raise exception 'chat rate limit' using errcode='P0001';
  end if;
  insert into public.round_messages(contest_id, display_name, body, sender_session_hash, created_at)
    values(cid, btrim(p_name), btrim(p_body), session_hash, at_time);
end $function$

CREATE OR REPLACE FUNCTION public.list_messages(p_token text, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(display_name text, body text, created_at timestamp with time zone) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare cid uuid;
begin
  cid := public.chat_contest(p_token);
  return query select m.display_name,m.body,m.created_at from (
    select r.* from public.round_messages r where r.contest_id=cid and r.removed_at is null
      and (p_since is null or r.created_at > p_since)
    order by r.created_at desc,r.id desc limit 200
  ) m order by m.created_at,m.id;
end $function$

CREATE OR REPLACE FUNCTION public.legacy_contest_open(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
 SELECT EXISTS(SELECT 1 FROM public.contests WHERE id=cid AND protocol=0);
$function$

CREATE OR REPLACE FUNCTION public.request_join(code text, display_name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE cid uuid; uid uuid := auth.uid();
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='AUTH_REQUIRED'; END IF;
 IF display_name IS NULL OR length(btrim(display_name)) NOT BETWEEN 1 AND 80 OR code IS NULL OR length(code)>32 THEN
  RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
 SELECT id INTO cid FROM public.contests WHERE invite_code=upper(btrim(code)) AND protocol=1 AND sync_enabled AND status='active' FOR UPDATE;
 IF cid IS NOT NULL THEN
  INSERT INTO public.contest_join_requests(contest_id,requester,requested_name) VALUES(cid,uid,btrim(display_name))
   ON CONFLICT (contest_id,requester) WHERE status='pending' DO NOTHING;
 END IF;
 -- Unknown and disabled codes intentionally have the identical public result.
 RETURN '{"status":"pending"}'::jsonb;
END $function$

CREATE OR REPLACE FUNCTION public.my_membership(contest_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='AUTH_REQUIRED'; END IF;
 RETURN (SELECT jsonb_build_object('role',m.role,'status',m.status,'player_id',m.player_id)
 FROM public.contest_memberships m WHERE m.contest_id=$1 AND m.user_id=auth.uid());
END $function$

CREATE OR REPLACE FUNCTION public.tournament_snapshot(contest_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE c public.contests; uid uuid := auth.uid(); rounds jsonb;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='AUTH_REQUIRED'; END IF;
  SELECT * INTO c FROM public.contests WHERE id = contest_id;
  IF c.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='FORBIDDEN'; END IF;
  IF NOT (
    (c.owner_id = uid AND NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false))
    OR EXISTS (SELECT 1 FROM public.contest_memberships m WHERE m.contest_id = c.id AND m.user_id = uid AND m.status = 'approved' AND m.role IN ('host', 'player', 'scorer'))
  ) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='FORBIDDEN'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id, 'number', r.round_number, 'name', r.name,
    'groups', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', g.id, 'name', g.name,
        'players', (
          SELECT coalesce(jsonb_agg(jsonb_build_object(
            'id', p.id, 'name', p.name,
            'scores', (
              SELECT jsonb_agg(s.strokes ORDER BY gs.hole)
              FROM generate_series(1, 18) AS gs(hole)
              LEFT JOIN LATERAL (
                SELECT e.strokes FROM public.score_events e
                WHERE e.contest_id = c.id AND e.round_id = r.id AND e.player_id = p.id AND e.hole = gs.hole AND e.cell_version IS NOT NULL
                ORDER BY e.cell_version DESC LIMIT 1
              ) s ON true
            )
          ) ORDER BY p.sort_order, p.name), '[]'::jsonb)
          FROM public.round_player_assignments a
          JOIN public.contest_players p ON p.id = a.player_id AND p.contest_id = a.contest_id
          WHERE a.contest_id = c.id AND a.round_id = r.id AND a.group_id = g.id
        )
      ) ORDER BY g.sort_order, g.name), '[]'::jsonb)
      FROM public.contest_groups g WHERE g.contest_id = c.id AND g.round_id = r.id
    )
  ) ORDER BY r.round_number), '[]'::jsonb) INTO rounds
  FROM public.contest_rounds r WHERE r.contest_id = c.id;
  RETURN jsonb_build_object('revision', c.sync_revision, 'rounds', rounds);
END $function$

CREATE OR REPLACE FUNCTION public.set_tournament_meta(contest_id uuid, is_tournament boolean, current_round integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE c public.contests; uid uuid := auth.uid();
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='AUTH_REQUIRED'; END IF;
  IF coalesce((auth.jwt()->>'is_anonymous')::boolean, false) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='HOST_REQUIRED'; END IF;
  SELECT * INTO c FROM public.contests WHERE id = contest_id FOR UPDATE;
  IF c.id IS NULL OR c.owner_id <> uid THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='HOST_REQUIRED'; END IF;
  IF NOT c.sync_enabled OR c.protocol <> 1 OR c.status <> 'active' THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='SYNC_PAUSED'; END IF;
  IF is_tournament IS NULL OR current_round IS NULL OR current_round NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contest_rounds r WHERE r.contest_id = c.id AND r.round_number = current_round) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='ROUND_NOT_READY'; END IF;
  UPDATE public.contests SET is_tournament = set_tournament_meta.is_tournament, current_round = set_tournament_meta.current_round WHERE id = c.id;
  RETURN jsonb_build_object('status', 'ok', 'is_tournament', is_tournament, 'current_round', current_round);
END $function$

CREATE OR REPLACE FUNCTION public.sync_round_bundle(contest_id uuid, payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE
  c public.contests; uid uuid := auth.uid(); rid uuid; n integer; local text;
  g jsonb; elem jsonb; gid uuid; pid uuid; glocal text; plocal text;
  gname text; pname text; tval text; st text; hcap numeric; sorder integer; gorder integer;
  keep uuid[] := ARRAY[]::uuid[]; seen uuid[] := ARRAY[]::uuid[];
  players jsonb; groups jsonb := '[]'::jsonb; d date; cdata jsonb;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='AUTH_REQUIRED'; END IF;
  IF coalesce((auth.jwt()->>'is_anonymous')::boolean, false) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='HOST_REQUIRED'; END IF;
  IF contest_id IS NULL OR payload IS NULL OR jsonb_typeof(payload) <> 'object' OR length(payload::text) > 200000 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
  IF payload ? 'groups' AND jsonb_typeof(payload->'groups') <> 'array' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
  SELECT * INTO c FROM public.contests WHERE id = contest_id FOR UPDATE;
  IF c.id IS NULL OR c.owner_id <> uid THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='HOST_REQUIRED'; END IF;
  IF NOT c.sync_enabled OR c.protocol <> 1 OR c.status <> 'active' THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='SYNC_PAUSED'; END IF;
  BEGIN
    n := CASE WHEN payload ? 'number' AND nullif(payload->>'number','') IS NOT NULL THEN (payload->>'number')::integer ELSE NULL END;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST';
  END;
  IF n IS NOT NULL AND n NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
  local := nullif(btrim(payload->>'local_id'), '');
  IF local IS NOT NULL THEN
    IF length(local) > 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
    SELECT m.server_id INTO rid FROM public.sync_id_map m WHERE m.contest_id = c.id AND m.kind = 'round' AND m.local_id = local;
  END IF;
  IF rid IS NULL AND payload->>'server_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    rid := (payload->>'server_id')::uuid;
    IF NOT EXISTS (SELECT 1 FROM public.contest_rounds r WHERE r.id = rid AND r.contest_id = c.id) THEN rid := NULL; END IF;
  END IF;
  IF n IS NOT NULL THEN
    SELECT r.id INTO rid FROM public.contest_rounds r WHERE r.contest_id = c.id AND r.round_number = n;
  END IF;
  IF rid IS NULL AND n IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='ROUND_NOT_READY'; END IF;
  BEGIN
    d := nullif(payload->>'date', '')::date;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST';
  END;
  IF payload ? 'course_data' AND payload->'course_data' IS NOT NULL AND jsonb_typeof(payload->'course_data') NOT IN ('object', 'null') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
  cdata := CASE WHEN payload->'course_data' IS NULL OR jsonb_typeof(payload->'course_data') = 'null' THEN NULL ELSE payload->'course_data' END;
  IF rid IS NULL THEN
    IF payload ? 'name' AND (payload->>'name' IS NULL OR length(btrim(payload->>'name')) NOT BETWEEN 1 AND 80) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
    INSERT INTO public.contest_rounds (contest_id, round_number, name, date, course_name, course_data)
    VALUES (c.id, n, coalesce(nullif(btrim(payload->>'name'), ''), 'Round ' || n), d, nullif(btrim(payload->>'course_name'), ''), cdata)
    RETURNING id INTO rid;
  ELSE
    UPDATE public.contest_rounds r SET
      name = CASE WHEN payload ? 'name' AND length(btrim(payload->>'name')) BETWEEN 1 AND 80 THEN btrim(payload->>'name') ELSE r.name END,
      date = CASE WHEN payload ? 'date' THEN d ELSE r.date END,
      course_name = CASE WHEN payload ? 'course_name' THEN nullif(btrim(payload->>'course_name'), '') ELSE r.course_name END,
      course_data = CASE WHEN payload ? 'course_data' THEN cdata ELSE r.course_data END
    WHERE r.id = rid AND r.contest_id = c.id;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='ROUND_NOT_READY'; END IF;
  END IF;
  IF local IS NOT NULL THEN
    INSERT INTO public.sync_id_map (contest_id, kind, local_id, server_id) VALUES (c.id, 'round', local, rid)
    ON CONFLICT ON CONSTRAINT sync_id_map_pkey DO UPDATE SET server_id = excluded.server_id;
  END IF;
  IF payload ? 'groups' THEN
    DELETE FROM public.round_player_assignments a WHERE a.contest_id = c.id AND a.round_id = rid;
    FOR g IN SELECT value FROM jsonb_array_elements(payload->'groups') LOOP
      IF jsonb_typeof(g) <> 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      gname := btrim(g->>'name');
      IF gname IS NULL OR length(gname) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      IF g ? 'tee_time' AND g->>'tee_time' IS NOT NULL AND length(g->>'tee_time') > 40 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      IF g ? 'external_id' AND g->>'external_id' IS NOT NULL AND length(g->>'external_id') > 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      BEGIN
        gorder := coalesce((nullif(g->>'sort_order', ''))::integer, 0);
      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST';
      END;
      IF gorder < 0 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      gid := NULL; glocal := nullif(btrim(g->>'local_id'), '');
      IF glocal IS NOT NULL THEN
        IF length(glocal) > 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        SELECT m.server_id INTO gid FROM public.sync_id_map m WHERE m.contest_id = c.id AND m.kind = 'group' AND m.local_id = glocal;
      END IF;
      IF gid IS NULL AND g->>'server_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN gid := (g->>'server_id')::uuid; END IF;
      IF gid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.contest_groups cg WHERE cg.id = gid AND cg.contest_id = c.id) THEN
        IF EXISTS (SELECT 1 FROM public.contest_groups cg WHERE cg.id = gid) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
      END IF;
      IF gid IS NULL OR NOT EXISTS (SELECT 1 FROM public.contest_groups cg WHERE cg.id = gid AND cg.contest_id = c.id) THEN
        INSERT INTO public.contest_groups (id, contest_id, round_id, name, tee_time, external_id, sort_order)
        VALUES (coalesce(gid, gen_random_uuid()), c.id, rid, gname, nullif(g->>'tee_time', ''), nullif(g->>'external_id', ''), gorder)
        RETURNING id INTO gid;
      ELSE
        DELETE FROM public.round_player_assignments a WHERE a.contest_id = c.id AND a.group_id = gid;
        UPDATE public.contest_groups cg SET name = gname, tee_time = nullif(g->>'tee_time', ''), external_id = nullif(g->>'external_id', ''),
          sort_order = gorder, round_id = rid
        WHERE cg.id = gid AND cg.contest_id = c.id RETURNING cg.id INTO gid;
      END IF;
      IF glocal IS NOT NULL THEN
        INSERT INTO public.sync_id_map (contest_id, kind, local_id, server_id) VALUES (c.id, 'group', glocal, gid)
        ON CONFLICT ON CONSTRAINT sync_id_map_pkey DO UPDATE SET server_id = excluded.server_id;
      END IF;
      keep := keep || gid;
      players := '[]'::jsonb;
      FOR elem IN SELECT value FROM jsonb_array_elements(coalesce(g->'players', '[]'::jsonb)) LOOP
        IF jsonb_typeof(elem) <> 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        pname := btrim(elem->>'name');
        IF pname IS NULL OR length(pname) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        st := coalesce(nullif(btrim(elem->>'status'), ''), 'active');
        IF st NOT IN ('active', 'WD', 'NS') THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        BEGIN
          hcap := coalesce((nullif(elem->>'handicap', ''))::numeric, 0);
          sorder := coalesce((nullif(elem->>'sort_order', ''))::integer, 0);
        EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST';
        END;
        IF sorder < 0 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        IF elem ? 'course_handicaps' AND elem->'course_handicaps' IS NOT NULL AND jsonb_typeof(elem->'course_handicaps') NOT IN ('object', 'null') THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        tval := nullif(btrim(elem->>'team'), '');
        IF tval IS NOT NULL AND tval NOT IN ('A', 'B') THEN tval := NULL; END IF;
        pid := NULL; plocal := nullif(btrim(elem->>'local_id'), '');
        IF plocal IS NOT NULL THEN
          IF length(plocal) > 80 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
          SELECT m.server_id INTO pid FROM public.sync_id_map m WHERE m.contest_id = c.id AND m.kind = 'player' AND m.local_id = plocal;
        END IF;
        IF pid IS NULL AND elem->>'server_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN pid := (elem->>'server_id')::uuid; END IF;
        IF pid IS NULL THEN pid := gen_random_uuid(); END IF;
        IF pid = ANY(seen) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
        seen := seen || pid;
        IF EXISTS (SELECT 1 FROM public.contest_players cp WHERE cp.id = pid AND cp.contest_id <> c.id) THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_PLAYER'; END IF;
        INSERT INTO public.contest_players (id, contest_id, name, handicap, team, sort_order, status, course_handicaps)
        VALUES (pid, c.id, pname, hcap, tval, sorder, st,
          CASE WHEN elem->'course_handicaps' IS NULL OR jsonb_typeof(elem->'course_handicaps') = 'null' THEN NULL ELSE elem->'course_handicaps' END)
        ON CONFLICT (id) DO UPDATE SET
          name = excluded.name, handicap = excluded.handicap,
          team = CASE WHEN excluded.team IN ('A', 'B') THEN excluded.team ELSE public.contest_players.team END,
          sort_order = excluded.sort_order, status = excluded.status, course_handicaps = excluded.course_handicaps
        WHERE public.contest_players.contest_id = excluded.contest_id;
        IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_PLAYER'; END IF;
        IF plocal IS NOT NULL THEN
          INSERT INTO public.sync_id_map (contest_id, kind, local_id, server_id) VALUES (c.id, 'player', plocal, pid)
          ON CONFLICT ON CONSTRAINT sync_id_map_pkey DO UPDATE SET server_id = excluded.server_id;
        END IF;
        players := players || jsonb_build_array(jsonb_build_object('local_id', plocal, 'id', pid));
      END LOOP;
      groups := groups || jsonb_build_array(jsonb_build_object('local_id', glocal, 'id', gid, 'players', players));
    END LOOP;
    DELETE FROM public.contest_groups cg WHERE cg.contest_id = c.id AND cg.round_id = rid AND NOT (cg.id = ANY(keep));
    FOR g IN SELECT value FROM jsonb_array_elements(groups) LOOP
      gid := (g->>'id')::uuid;
      FOR elem IN SELECT value FROM jsonb_array_elements(g->'players') LOOP
        INSERT INTO public.round_player_assignments (contest_id, round_id, player_id, group_id)
        VALUES (c.id, rid, (elem->>'id')::uuid, gid);
      END LOOP;
    END LOOP;
    DELETE FROM public.group_submissions s WHERE s.contest_id = c.id AND s.round_id = rid;
    UPDATE public.contest_rounds r SET assignment_revision = r.assignment_revision + 1 WHERE r.id = rid;
  END IF;
  RETURN jsonb_build_object('round_id', rid, 'groups', groups);
END $function$

CREATE OR REPLACE FUNCTION public.write_score(contest_id uuid, round_id uuid, player_id uuid, hole integer, action text, strokes integer, expected_version bigint, op_id uuid, request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE c public.contests; uid uuid := auth.uid(); prior public.operation_receipts; cell public.score_events;
 version bigint; fingerprint text; answer jsonb; resolved uuid; allowed boolean;
BEGIN
 SELECT * INTO c FROM public.contests WHERE id=$1 FOR UPDATE;
 IF uid IS NULL OR c.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='FORBIDDEN'; END IF;
 IF NOT c.sync_enabled OR c.protocol<>1 OR c.status<>'active' THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='SYNC_PAUSED'; END IF;
 IF $2 IS NULL THEN SELECT r.id INTO resolved FROM public.contest_rounds r WHERE r.contest_id=$1 AND r.round_number=1;
 ELSE SELECT r.id INTO resolved FROM public.contest_rounds r WHERE r.id=$2 AND r.contest_id=$1; END IF;
 IF resolved IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='ROUND_NOT_READY'; END IF;
 allowed := (c.owner_id=uid AND NOT coalesce((auth.jwt()->>'is_anonymous')::boolean,false))
  OR EXISTS(SELECT 1 FROM public.contest_memberships m WHERE m.contest_id=$1 AND m.user_id=uid AND m.status='approved' AND m.role='player' AND m.player_id=$3
    AND (NOT EXISTS(SELECT 1 FROM public.round_player_assignments a WHERE a.contest_id=$1 AND a.round_id=resolved)
      OR EXISTS(SELECT 1 FROM public.round_player_assignments a WHERE a.contest_id=$1 AND a.round_id=resolved AND a.player_id=$3)))
  OR EXISTS(SELECT 1 FROM public.contest_memberships m
    JOIN public.round_scorer_scopes s ON s.contest_id=m.contest_id AND s.user_id=m.user_id AND s.status='approved' AND s.round_id=resolved
    JOIN public.round_player_assignments a ON a.contest_id=s.contest_id AND a.round_id=s.round_id AND a.group_id=s.group_id AND a.player_id=$3
    WHERE m.contest_id=$1 AND m.user_id=uid AND m.status='approved' AND m.role='scorer');
 IF NOT allowed THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='FORBIDDEN'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.contest_players p WHERE p.id=$3 AND p.contest_id=$1) OR $4 IS NULL OR $4 NOT BETWEEN 1 AND 18
 OR $5 IS NULL OR $5 NOT IN ('set','clear') OR ($5='set' AND ($6 IS NULL OR $6 NOT BETWEEN 1 AND 15)) OR ($5='clear' AND $6 IS NOT NULL)
 OR $7 IS NULL OR $7<0 OR $8 IS NULL OR $9 IS NULL OR length($9) NOT BETWEEN 1 AND 256 THEN
  RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_SCORE'; END IF;
 fingerprint := encode(extensions.digest(jsonb_build_array($1,$2,$3,$4,$5,$6,$7,$9)::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(uid::text||':'||$8::text,0));
 SELECT * INTO prior FROM public.operation_receipts r WHERE r.actor=uid AND r.op_id=$8 FOR UPDATE;
 IF FOUND THEN
  IF prior.contest_id<>$1 OR prior.request_hash<>fingerprint THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='OP_REUSED'; END IF;
  RETURN prior.result;
 END IF;
 SELECT * INTO cell FROM public.score_events e WHERE e.contest_id=$1 AND e.round_id = resolved AND e.player_id=$3 AND e.hole=$4
 AND e.cell_version IS NOT NULL ORDER BY e.cell_version DESC LIMIT 1 FOR UPDATE;
 version := coalesce(cell.cell_version,0);
 IF version<>$7 THEN answer := jsonb_build_object('status','conflict','version',version,'strokes',cell.strokes,'revision',c.sync_revision);
 ELSE
  UPDATE public.contests SET sync_revision=sync_revision+1 WHERE id=$1 RETURNING * INTO c;
  INSERT INTO public.score_events(contest_id,round_id,player_id,hole,action,strokes,entered_by,actor,cell_version,contest_revision,op_id,request_hash)
   VALUES($1,resolved,$3,$4,$5,$6,uid,uid,version+1,c.sync_revision,$8,fingerprint);
  DELETE FROM public.group_submissions s USING public.round_player_assignments a
   WHERE a.contest_id=$1 AND a.round_id=resolved AND a.player_id=$3 AND s.contest_id=a.contest_id AND s.round_id=a.round_id AND s.group_id=a.group_id;
  answer := jsonb_build_object('status','accepted','version',version+1,'strokes',$6,'revision',c.sync_revision);
 END IF;
 INSERT INTO public.operation_receipts(actor,op_id,request_hash,contest_id,result) VALUES(uid,$8,fingerprint,$1,answer);
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.is_contest_owner(p_contest uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
  select exists(select 1 from public.contests c where c.id = p_contest and c.owner_id = auth.uid());
$function$

CREATE OR REPLACE FUNCTION public.create_share_link(p_local_id text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare r public.published_rounds; token text;
begin
  select * into r from public.published_rounds where owner_id=auth.uid() and local_id=p_local_id for update;
  if not found or not exists(select 1 from public.contests where id=r.contest_id and owner_id=auth.uid()) then raise exception 'owner required'; end if;
  if r.ended_at + interval '7 days' <= now() then raise exception 'round expired'; end if;
  token := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');
  insert into public.share_links(token_hash,contest_id,expires_at)
    values(encode(sha256(convert_to(token,'UTF8')),'hex'),r.contest_id,coalesce(r.ended_at + interval '7 days','infinity'::timestamptz));
  return token;
end $function$

CREATE OR REPLACE FUNCTION public.list_host_messages(p_local_id text) RETURNS TABLE(id uuid, display_name text, body text, created_at timestamp with time zone) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare cid uuid;
begin
  select r.contest_id into cid from public.published_rounds r join public.contests c on c.id=r.contest_id
    where r.local_id=p_local_id and r.owner_id=auth.uid() and c.owner_id=auth.uid()
      and not coalesce((auth.jwt()->>'is_anonymous')::boolean,false);
  if cid is null then raise exception 'owner required'; end if;
  return query select m.id,m.display_name,m.body,m.created_at from (
    select r.* from public.round_messages r where r.contest_id=cid and r.removed_at is null
    order by r.created_at desc,r.id desc limit 200
  ) m order by m.created_at,m.id;
end $function$

CREATE OR REPLACE FUNCTION public.revoke_share_links(p_local_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare cid uuid;
begin
  select r.contest_id into cid from public.published_rounds r join public.contests c on c.id=r.contest_id
    where r.owner_id=auth.uid() and c.owner_id=auth.uid() and r.local_id=p_local_id for update of r;
  if cid is null then raise exception 'owner required'; end if;
  update public.share_links set revoked_at=now() where contest_id=cid and revoked_at is null;
end $function$

CREATE OR REPLACE FUNCTION public.publish_shared_round(p_local_id text, p_snapshot jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare r public.published_rounds; cid uuid; clean jsonb; ended timestamptz;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'owner required'; end if;
  if length(p_local_id) not between 1 and 200 or pg_column_size(p_snapshot) > 100000 then raise exception 'invalid snapshot'; end if;
  -- Serialize creation and updates for a local contest, including across devices.
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || ':' || p_local_id,0));
  clean := public.sanitize_shared_round(p_snapshot);
  select * into r from public.published_rounds where owner_id = auth.uid() and local_id = p_local_id for update;
  if found then
    cid := r.contest_id;
    if not exists(select 1 from public.contests where id = cid and owner_id = auth.uid()) then raise exception 'owner required'; end if;
    ended := r.ended_at;
  else
    insert into public.contests(owner_id,name,course,invite_code)
      values(auth.uid(),'Shared round','{}'::jsonb,translate(upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),'01','GH')) returning id into cid;
  end if;
  if (clean->>'completed')::boolean and ended is null then ended := now(); end if;
  insert into public.published_rounds(contest_id,owner_id,local_id,snapshot,ended_at)
    values(cid,auth.uid(),p_local_id,clean,ended)
    on conflict(contest_id) do update set snapshot=excluded.snapshot, ended_at=excluded.ended_at, updated_at=now();
  -- Active links have no scheduled round end. Completion fixes their expiry once.
  if ended is not null then update public.share_links set expires_at=least(expires_at,ended + interval '7 days') where contest_id=cid; end if;
end $function$

CREATE OR REPLACE FUNCTION public.remove_message(p_message_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
begin
  update public.round_messages m set removed_at=coalesce(m.removed_at,clock_timestamp())
  where m.id=p_message_id and exists (
    select 1 from public.published_rounds r join public.contests c on c.id=r.contest_id
    where r.contest_id=m.contest_id and r.owner_id=auth.uid() and c.owner_id=auth.uid()
      and not coalesce((auth.jwt()->>'is_anonymous')::boolean,false)
  );
  if not found then raise exception 'owner required'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.decide_join_request(request_id uuid, approve boolean, player_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE cid uuid; c public.contests; r public.contest_join_requests; old_uid uuid;
BEGIN
 SELECT q.contest_id INTO cid FROM public.contest_join_requests q WHERE q.id=$1;
 SELECT * INTO c FROM public.contests WHERE id=cid FOR UPDATE;
 IF c.id IS NULL OR auth.uid() IS NULL OR c.owner_id<>auth.uid() OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) THEN
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='HOST_REQUIRED'; END IF;
 IF NOT c.sync_enabled OR c.protocol<>1 OR c.status<>'active' THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='SYNC_PAUSED'; END IF;
 SELECT * INTO r FROM public.contest_join_requests q WHERE q.id=$1 FOR UPDATE;
 IF r.status<>'pending' OR approve IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_REQUEST'; END IF;
 IF approve THEN
  IF NOT EXISTS(SELECT 1 FROM public.contest_players p WHERE p.id=$3 AND p.contest_id=cid) THEN
   RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_PLAYER'; END IF;
  IF r.requester=c.owner_id THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='HOST_SLOT'; END IF;
  -- An existing approved identity cannot silently acquire a second slot.
  IF EXISTS(SELECT 1 FROM public.contest_memberships m WHERE m.contest_id=cid AND m.user_id=r.requester AND m.status='approved') THEN
   RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='ALREADY_APPROVED'; END IF;
  SELECT p.user_id INTO old_uid FROM public.contest_players p WHERE p.id=$3;
  UPDATE public.contest_memberships m SET status='revoked',updated_at=now() WHERE m.contest_id=cid
    AND (m.player_id=$3 OR m.user_id=old_uid) AND m.status<>'revoked';
  -- Clear every legacy binding of the previous identity, not just the claimed slot.
  UPDATE public.contest_players p SET user_id=NULL WHERE p.contest_id=cid AND (p.id=$3 OR p.user_id=old_uid);
  INSERT INTO public.contest_memberships(contest_id,user_id,role,player_id,status) VALUES(cid,r.requester,'player',$3,'approved')
   ON CONFLICT (contest_id,user_id) DO UPDATE SET role='player',player_id=excluded.player_id,status='approved',updated_at=now();
 END IF;
 UPDATE public.contest_join_requests q SET status=CASE WHEN approve THEN 'approved' ELSE 'rejected' END,
  desired_player_id=CASE WHEN approve THEN $3 ELSE NULL END,decided_by=auth.uid(),decided_at=now() WHERE q.id=$1;
 RETURN jsonb_build_object('status',CASE WHEN approve THEN 'approved' ELSE 'rejected' END);
END $function$

CREATE OR REPLACE FUNCTION public.allocate_join_code() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE candidate text; attempt integer;
BEGIN
 FOR attempt IN 1..32 LOOP
  candidate := public.join_code_candidate();
  PERFORM pg_advisory_xact_lock(hashtextextended('snapscore-code:'||candidate,0));
  IF NOT EXISTS (SELECT 1 FROM public.contests WHERE invite_code=candidate) THEN RETURN candidate; END IF;
 END LOOP;
 RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='CODE_EXHAUSTED';
END $function$

CREATE OR REPLACE FUNCTION public.guard_sync_legacy() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE cid uuid; p smallint;
BEGIN
 cid := CASE WHEN TG_OP='DELETE' THEN OLD.contest_id ELSE NEW.contest_id END;
 SELECT protocol INTO p FROM public.contests WHERE id=cid FOR UPDATE;
 IF p=1 THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='LEGACY_PROTOCOL'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.join_code_candidate() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
DECLARE candidate text := ''; bytes bytea := extensions.gen_random_bytes(6); i integer;
BEGIN
 FOR i IN 0..5 LOOP
  candidate := candidate || substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',get_byte(bytes,i)%32+1,1);
 END LOOP;
 RETURN candidate;
END $function$

CREATE OR REPLACE FUNCTION public.sanitize_shared_round(p jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path TO 'pg_catalog' AS $function$
declare players jsonb; games jsonb;
begin
  if jsonb_typeof(p->'players') is distinct from 'array' or jsonb_array_length(p->'players') > 40
    or jsonb_typeof(p->'games') is distinct from 'array' or jsonb_array_length(p->'games') > 30 then
    raise exception 'invalid snapshot';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'displayName', left(x->>'displayName',80),
    'scores', (select coalesce(jsonb_agg((n::text)::integer order by ord), '[]'::jsonb)
      from jsonb_array_elements(x->'scores') with ordinality as s(n,ord)
      where ord <= 18 and jsonb_typeof(n) = 'number' and n::text ~ '^[0-9]{1,2}$'),
    'total', (x->>'total')::integer, 'toPar', (x->>'toPar')::integer
  )), '[]'::jsonb) into players from jsonb_array_elements(p->'players') x;
  select coalesce(jsonb_agg(jsonb_build_object(
    'game', left(x->>'game',40),
    'standings', (select coalesce(jsonb_agg(jsonb_build_object(
      'displayName', left(s->>'displayName',80), 'units', (s->>'units')::numeric)), '[]'::jsonb)
      from jsonb_array_elements(x->'standings') s)
  )), '[]'::jsonb) into games from jsonb_array_elements(p->'games') x;
  return jsonb_build_object('completed', coalesce((p->>'completed')::boolean,false), 'players', players, 'games', games);
end $function$

CREATE OR REPLACE FUNCTION public.reserve_golfcore_call(p_endpoint text, p_monthly_cap integer, p_minute_cap integer) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE v_month text := to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM');
v_calls bigint; v_minute bigint; v_used bigint; v_tripped boolean; v_id bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(706241024);
 SELECT count(*), coalesce(bool_or(quota_tripped), false) INTO v_calls, v_tripped FROM golfcore_usage WHERE month = v_month;
 SELECT count(*) INTO v_minute FROM golfcore_usage WHERE called_at >= clock_timestamp() - interval '60 seconds';
 SELECT greatest(0, ratelimit_limit - ratelimit_remaining) INTO v_used FROM golfcore_usage
 WHERE month = v_month AND ratelimit_limit IS NOT NULL AND ratelimit_remaining IS NOT NULL ORDER BY called_at DESC, id DESC LIMIT 1;
 IF v_tripped OR greatest(v_calls, coalesce(v_used,0)) >= LEAST(coalesce(p_monthly_cap, 500), 500)
 OR v_minute >= LEAST(coalesce(p_minute_cap, 9), 9) THEN RETURN NULL; END IF;
 INSERT INTO golfcore_usage(month, endpoint, status) VALUES (v_month, p_endpoint, 0) RETURNING id INTO v_id;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.chat_contest(p_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$
declare link public.share_links;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then raise exception 'invalid link'; end if;
  select * into link from public.share_links where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex');
  if not found then raise exception 'invalid link'; end if;
  if link.revoked_at is not null then raise exception 'revoked link'; end if;
  if link.expires_at <= clock_timestamp() then raise exception 'expired link'; end if;
  return link.contest_id;
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_golfcore_usage(p_usage_id bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE v_row golfcore_usage%ROWTYPE; v_count bigint; v_used bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(706241024);
 SELECT * INTO v_row FROM golfcore_usage WHERE id = p_usage_id;
 IF v_row.ratelimit_limit IS NULL OR v_row.ratelimit_remaining IS NULL THEN RETURN; END IF;
 SELECT count(*) INTO v_count FROM golfcore_usage WHERE month = v_row.month;
 v_used := greatest(0, v_row.ratelimit_limit - v_row.ratelimit_remaining);
 IF abs(v_used - v_count)::numeric / greatest(1, v_count) > 0.02 THEN
  INSERT INTO golfcore_usage_drift(month, ledger_calls, header_used) VALUES (v_row.month, v_count, v_used);
 END IF;
END $function$
